  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Voriconazole, a fluorinated azole with heteroaromatic and fluorophenyl motifs, has a mean absolute oral bioavailability of 96% in healthy volunteers, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Linezolid has 100% absolute oral bioavailability in healthy volunteers, demonstrating that a polar, functionalized oral drug can be completely absorbed; this supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Aprepitant, a lipophilic oral drug with fluorophenyl and heteroaromatic features, has an absolute oral bioavailability of approximately 60-65%, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Voriconazole absolute bioavailability was 90% in pediatric patients, providing a direct absolute measurement that supports high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Theophylline absolute bioavailability from an oral syrup was 91.9%, showing excellent absorption for an N-methylated heteroaromatic system relevant to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "A closely related chiral heteroaromatic compound was predicted to have 80% human oral bioavailability, directly supporting high F for this chemical class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred experimental evidence points to oral bioavailability well above 20%; the lowest reported values are approximately 45-60%, and several absolute measurements are 90-100%. Therefore the query is predicted high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "The highest-transfer evidence comes from smaller, simpler drugs; the query's larger fused-ring scaffold may have different solubility or efflux behavior.",
    "No retrieved evidence reports F below 20%, so the low-F alternative is not directly supported."
  ],
